function page(){
 activeTechnique=-1;state.current=-1;state.step=0;state.max=0;
 document.title="جلسه چهارم | فن بیان و مهارت‌های کلامی رؤسای شعب";
 const app=document.getElementById("app");if(!app)return;
 app.innerHTML='<header class="s4-topbar"><div class="s4-topinside"><div class="s4-brand"><img src="../assets/company-logos/alborz.svg" alt="نشان بیمه البرز"><div><strong>آکادمی ارتباطات اثربخش</strong><small>بیمه البرز · رؤسای شعب · جلسه چهارم</small></div></div><a class="s4-home" href="?course=communication">⌂ خانه دوره</a></div></header>'+
 '<main class="s4-root"><div class="wrap">'+
 '<section class="s4-hero"><div class="s4-hero-copy"><span class="s4-chip">جلسه چهارم · ۱۲۰ دقیقه</span><h1>فن بیان مدیریتی، لحن و زبان بدن</h1><p>از گفت‌وگوی روزمره و مدیریت اضطراب تا بیان روان، پرمغز و ارائه حرفه‌ای</p></div><img class="s4-hero-photo" src="assets/session2-hero-hq.webp" alt="فن بیان و ارتباط حرفه‌ای در محیط شعبه"></section>'+
 '<section class="s4-overview"><div class="s4-heading"><h2>شش تکنیک فن بیان، گفت‌وگو و ارائه</h2><p>روی تکنیک بزنید تا توضیح و مثال آن باز شود.</p></div><div class="s4-techs">'+techniques.map((t,i)=>'<button type="button" class="s4-tech" data-s4-tech="'+i+'" aria-expanded="false" aria-controls="s4-tech-detail"><span class="s4-tech-icon">'+t[0]+'</span><strong>'+escapeHtml(t[1])+'</strong><small>مثال و توضیح ＋</small></button>').join("")+'</div><div id="s4-tech-detail" class="s4-tech-detail" hidden tabindex="-1" aria-live="polite"></div>'+
 '<details class="s4-science"><summary>پشتوانه علمی و مرز تفسیر زبان بدن</summary><p>این شش تکنیک برای تمرین رفتاری در شعب بیمه طراحی شده‌اند؛ نه یک مقیاس استاندارد روان‌شناختی. اولویت با وضوح پیام، امکان پرسش و رفتار قابل مشاهده مدیر است. هیچ نشانه منفرد زبان بدن، مانند جهت نگاه یا دست‌به‌سینه بودن، معنای قطعی ندارد. نسبت ۷/۳۸/۵۵ نیز قانون عمومی ارتباطات نیست. وضوح پیام، انتخاب واژه، لحن، سرعت، مکث و هماهنگی کلام و رفتار در فن بیان مدیریتی اهمیت دارند.</p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10623623/" target="_blank" rel="noopener noreferrer">مرجع پژوهشی: چهار سوءبرداشت رایج درباره ارتباط غیرکلامی</a> · <a href="https://www.tandfonline.com/doi/abs/10.1080/03634529709379073" target="_blank" rel="noopener noreferrer">مرز اعتبار فرمول ۷/۳۸/۵۵</a> · <a href="https://www.ccl.org/articles/leading-effectively-articles/communication-1-idea-3-facts-5-tips/" target="_blank" rel="noopener noreferrer">ارتباط اثربخش در رهبری، CCL</a></details></section>'+
 '<section class="s4-lab"><div class="s4-heading"><h2>آزمایشگاه فن بیان، گفت‌وگو و ارائه</h2><p>هر کیس یک گفت‌وگو یا ارائه واقعی دارد؛ بار اول بدون قواعد، بار دوم با سه قاعده قابل مشاهده اجرا کنید.</p></div><div class="s4-cases">'+cases.map((c,i)=>'<button type="button" class="s4-case" data-s4-case="'+i+'" aria-expanded="false"><span class="s4-number">کیس '+digits(i+1)+'</span><span class="s4-case-label"><strong>'+escapeHtml(c.title)+'</strong><small>'+escapeHtml(c.role)+' · '+escapeHtml(c.skill)+'</small></span><span class="s4-arrow">←</span></button>').join("")+'</div><div id="s4-focus" class="s4-focus" aria-live="polite"></div></section>'+
 '<details class="s4-instructor"><summary>🎓 راهنمای مدرس · اجرای ۱۲۰ دقیقه‌ای</summary><div class="s4-plan"><div><strong>۱۰ دقیقه</strong><span>گفت‌وگو یا ارائه ۳۰ثانیه‌ای اولیه و خودارزیابی تسلط</span></div><div><strong>۲۴ دقیقه</strong><span>شش تکنیک فن بیان و ارتباط کلامی؛ هرکدام ۴ دقیقه</span></div><div><strong>۲۰ دقیقه</strong><span>آزمایشگاه اول: کیس‌های ۱ تا ۴ (موازی در زوج‌ها)</span></div><div><strong>۲۰ دقیقه</strong><span>آزمایشگاه دوم: کیس‌های ۵ تا ۸ (موازی در زوج‌ها)</span></div><div><strong>۲۰ دقیقه</strong><span>آزمایشگاه سوم: کیس‌های ۹ تا ۱۲ (موازی در زوج‌ها)</span></div><div><strong>۶ دقیقه</strong><span>آزمون پایانی و پاسخنامه؛ سپس ۱۲ دقیقه اجرای دوباره و Feedback</span></div></div><p>اجرای آنلاین دو‌نفره در اتاق‌های موازی: هر کیس ۵ دقیقه؛ ۹۰ ثانیه اجرای اول، ۳۰ ثانیه قواعد، ۹۰ ثانیه اجرای اصلاح‌شده و ۹۰ ثانیه بازخورد. ۱۰ + ۲۴ + ۶۰ + ۶ + ۱۲ + ۸ دقیقه شناوری = ۱۲۰ دقیقه. در آغاز و پایان، میزان تسلط در گفت‌وگوی فردی و ارائه در جمع را جداگانه از ۰ تا ۱۰ خودارزیابی کنید.</p></details>'+
 '</div></main>';
}
